INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p170950-me472', 'stk-_20061', 'ME 472', 'info', '{"desc": "احسن واحد يدرس corrosion هو الكنج الدكتور علام\n\nانصحك لا تاخذ مع زهير قاسم والله ماتفهم لانه مش فاهم ماادري ليش يعطونه هل الماده\nعلام وبس, بعدين زهير قاسم الاختبار النهائي 500 slides لازم تحفظهم مزبوط مش تفهمها\n---------------------------------------------------------------------\nماده pumping دائما محتكره من قبل الدكتور بدر حسن وهو اللي مؤلف كتابها\n------------------------------------------------------------------------\nماده vibration احسن واحد يعطيها الدكتور الخلوق سونار والنصار\n=========================================\nماده heat exchanger احسن واحد او محتكره من قبل زبير روعههههههههههههه\n----------------------------------------------\n\nاي استفسار انا مو جود لو تبي اقول لك عن اي دكتور في الميكانيكال\n\nاو حتى السكرتاريه: لطيف وجميل والشباب الحلوين الباقين@18@", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-472/56329/8", "user": "_20061", "ts": 1179966948000, "tid": 56329, "pn": 8}}', 1179966948000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p27002-me472', 'stk-mrxxxxxx', 'ME 472', 'info', '{"desc": "الله يعينك\n\nالله عينك…عزالله انك توهقت…شرح ازفت من الزفت…نوت وخط وكتابه يبي لك مترجم يفك الطلاسم…الماده وخصوصا بدايتها…بيور كيميكال…يعني كلها مامرت علينا قبل في الميكانيكال…ولا موضوع من مواضيعها…بس خلنا نرجع لزكي…لا نوت لا شرح وكلامه متناقض والمعلومات غلط حتى الفاينل جايب الاسئله غلط ومعها ورقه لتصحيح الاخطاء والورقه هذي كلها اغلاط…لكن…واقول لكن بعد…مستحيل تلاقي دكتور في الجامعه يكرر الا سئله مثله…كوبي بيست…وخصوصا الهلب سشن…ما يحتاج تقرا السؤال…على طول تشوف الرسمه وتروح وانت مغمض تكتب الجواب…يعني مافيه ولا طالب في راسه معلومه وحده عن الكوروجن…بس القريد معقول…او نقدر نقول جيد جدا…بيعطيك اكثر من اللي تستاهل…واكيد بتطلبني في الاوراق والاختبارات حقته…وانا بقول لك كم تدفع؟…لا لا تصدق امزح…انت او اي واحد من الشباب يامر عليها امر…وبالتوفيق والله يعينكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-472/23720/3", "user": "Mrxxxxxx", "ts": 1058775381000, "tid": 23720, "pn": 3}}', 1058775381000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1161235-me472', 'stk-mechanical_boy', 'ME 472', 'info', '{"desc": "^^^\n\nكنت احفظ اي شي يحطه من هوموركات وكويزات وسلايدات على سطح المكتب وعندي ملف كامل للكورس هذا بس ماعرف شلون ارفعه حط طريقة الرفع وابشر ابحطها بتقييم الكورسات عشان يستفيدون الطلاب\n\nعلى الرغم اني مانصح اي طالب يفكر انه ياخذ الكورس هذا على انه كورس(قريد) الكورس طويل ويبيله فهم وحفظ بشكل اكبر والدكتور تعبنا معاه صراحه بس ماينلام لانه كورس دسم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me472/137674/5", "user": "Mechanical_Boy", "ts": 1357778654000, "tid": 137674, "pn": 5}}', 1357778654000, 1794792307, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
